 document.querySelectorAll('#panel-goal .calc-step[data-step]').forEach(n=>{if(r.valid&&r.missing===0&&Number(n.dataset.step)>=3)n.dataset.skip='1';else delete n.dataset.skip;});
 const scenarios=state.activities.map(a=>({...a,investment:a.owned?0:a.investment})).map(a=>({a,r:calculation(a)}));
 const valid=scenarios.filter(x=>x.r.valid&&x.r.missing>0),fastest=valid.slice().sort((a,b)=>a.r.totalMinutes-b.r.totalMinutes)[0]?.a.id,cheapest=valid.slice().sort((a,b)=>a.a.investment-b.a.investment)[0]?.a.id;
