 if(x.accessible.length>1)html+='<div class="c-detail">'+'<div class="calc-table-wrap" tabindex="0"><table class="calc-table"><caption>Com '+nf.format(state.inverse.minutes||0)+' min, as atividades possíveis</caption><thead><tr><th scope="col">Atividade</th><th scope="col">Missões concluídas</th><th scope="col">Ganho</th></tr></thead><tbody>'+x.accessible.map(a=>'<tr'+(a.id===state.inverse.selected?' class="is-selected"':'')+'><th scope="row">'+esc(a.name)+(a===x.best?' · a melhor':'')+'</th><td>'+nf.format(a.runs)+'</td><td>'+money(a.profit)+'</td></tr>').join('')+'</tbody></table></div></div>';
