const normalize=s=>String(s).replace(/ß/g,'ss').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’‘]/g,"'").replace(/[\u00a0\u202f]/g,' ');
function near(a,b){if(Math.abs(a.length-b.length)>1)return false;let i=0,j=0,n=0;while(i<a.length&&j<b.length){if(a[i]===b[j]){i++;j++;continue;}if(++n>1)return false;if(a.length>=b.length)i++;if(b.length>=a.length)j++;}return n+(i<a.length||j<b.length?1:0)<=1;}
function searchMatch(item,q){let hay=normalize((item.brand||'')+' '+item.name+' '+item.category+' '+(labels[item.type]||'')+' '+(item.aliases||''));const aliases={voiture:'vehicule',bagnole:'vehicule',flingue:'equipement',arme:'equipement',maison:'demeure',mission:'activite'};return normalize(q).split(/\s+/).filter(Boolean).every(t=>{t=aliases[t]||t;return hay.includes(t)||(t.length>=5&&hay.split(/[^a-z0-9]+/).some(w=>near(t,w)));});}
