/* v7.67 : cases remplies par l'IA de la barre « Que veux-tu calculer ? » (fonction /api/ia, API Claude). L'IA ne renvoie que des
   chemins du scénario et des valeurs écrites par le joueur : chemins limités à cette liste, chaque valeur validée par
   B.validate (une valeur refusée est ignorée), puis le même chargement qu'un calcul ouvert (restore). Les chiffres de la
   réponse viennent ensuite du moteur, comme pour une saisie à la main. */
const AI_PATHS=/^(?:goal\.(?:capital|reserve|hourly|dailyMinutes|players|target|meaning|selected|plannedSpend|upkeepPerSession|deadlineDays)|model|activities\.[0-2]\.(?:name|reward|cost|duration|prep|prepOnce|cooldown|share|players|investment)|session\.(?:minutes|maxRepeat|daysPerWeek|usualMinutes|enabled)|inverse\.(?:minutes|selected)|assets\.\d{1,2}\.(?:name|price|extras|fees|owned|role|incomeMode|boostHourly|resale|utility|requires|usage\.perSession|capabilities\.(?:terrain|seats))|purchase\.key|order\.(?:keys|objective)|roi\.(?:key|mode|revenueHourly|costHourly|hours|activityIds|gainPercent|durationReduction)|budget\.(?:source|extra|allocations\.[0-4])|compare\.(?:keys|criterion|hours)|analysis\.(?:horizon\.sessions|need\.(?:terrain|passengers|cargo)|priority|simulations\.[a-z-]+|sim\.[a-z-]+\.[a-zA-Z]+)|plan\.(?:goal\.(?:kind|target|name|price|meaning|targetUnits)|source|situation\.(?:capital|reserve|hourly|dailyMinutes|daysPerWeek|upkeepPerSession|players)|deadlineDays|priority|strategy|maxRepeat|missions\.\d\.(?:name|reward|cost|duration|prep|cooldown|share|players|investment|once)|prerequisites\.\d\.(?:name|price|minutes|boostHourly|usagePerSession)))$/;
function setOn(obj,path,value){const parts=path.split('.');let o=obj;for(let i=0;i<parts.length-1;i++){if(!o||typeof o!=='object'||!Object.prototype.hasOwnProperty.call(o,parts[i]))return false;o=o[parts[i]];}const k=parts.at(-1);if(!o||typeof o!=='object'||!Object.prototype.hasOwnProperty.call(o,k))return false;o[k]=value;return true;}
function withCases(base,cases){let next=validConfig(clone(base));const kept=[];for(const c of Array.isArray(cases)?cases:[]){if(!c||typeof c.chemin!=='string'||!AI_PATHS.test(c.chemin))continue;const trial=clone(next);if(!setOn(trial,c.chemin,c.valeur))continue;try{next=validConfig(trial);kept.push(c.chemin);}catch{/* valeur refusée par le scénario : ignorée */}}return {next,kept};}
const AI_TOOLS=['goal','purchase','session','budget','order','roi','activities','compare','plan'];
function applyAI(tool,cases,message){const {next,kept}=withCases(state,cases);if(AI_TOOLS.includes(tool))next.tab=tool;restore(next,message||'Campos preenchidos a partir da sua frase.');openTab(next.tab);return kept;}
function scenarioSummary(tool,cases){const {next,kept}=withCases(state,cases);return kept.length?workspace.summary(AI_TOOLS.includes(tool)?tool:state.tab,next):null;}
/* Résumé de l'état envoyé avec la demande (clés et noms nécessaires pour viser les bonnes cases ; aucune donnée personnelle) */
function brief(){const g=state.goal;return JSON.stringify({outil:state.tab,model:state.model,goal:{capital:g.capital,target:g.target,hourly:g.hourly,reserve:g.reserve,dailyMinutes:g.dailyMinutes,players:g.players,meaning:g.meaning},achats:state.assets.map((a,i)=>({i,key:a.key,name:a.name,price:a.price,owned:a.owned,role:a.role})),activites:state.activities.map((a,i)=>({i,id:a.id,name:a.name,reward:a.reward,duration:a.duration})),purchase:state.purchase.key,roi:{key:state.roi.key,mode:state.roi.mode},compare:state.compare.keys,order:state.order.keys}).slice(0,3000);}
window.LKCalculator={applyAI,scenarioSummary,brief,openTab,applyGoal(values){for(const k of ['capital','target','hourly','dailyMinutes'])if(Number.isFinite(values[k])){state.goal[k]=values[k];const f=$('f-goal-'+k);if(f)f.value=values[k];}if(values.hourly!==undefined){state.model='continuous';$('f-model').value='continuous';}changed();openTab('goal');},selectItem(id){const item=catalogue.find(x=>x.id===id);if(item)selectItem(item);}};
